function floodFill(image, row, col, color) {
  const old = image[row][col];
  if (old === color) {
    return;
  }
  const rows = image.length;
  const cols = image[0].length;
  const stack = [[row, col]];
  while (stack.length > 0) {
    const [r, c] = stack.pop();
    // A cell can be on the stack twice. Skip it once it's painted.
    if (image[r][c] !== old) {
      continue;
    }
    image[r][c] = color;
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] === old) {
        stack.push([nr, nc]);
      }
    }
  }
}

