#include <stack>
#include <utility>
#include <vector>

void floodFill(std::vector<std::vector<int>>& image, int row, int col, int color) {
    int old = image[row][col];
    if (old == color) {
        return;
    }
    int rows = image.size();
    int cols = image[0].size();
    const int steps[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    std::stack<std::pair<int, int>> stack;
    stack.push({row, col});
    while (!stack.empty()) {
        auto [r, c] = stack.top();
        stack.pop();
        // A cell can be on the stack twice. Skip it once it's painted.
        if (image[r][c] != old) {
            continue;
        }
        image[r][c] = color;
        for (const auto& step : steps) {
            int nr = r + step[0];
            int nc = c + step[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] == old) {
                stack.push({nr, nc});
            }
        }
    }
}

