import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    static void floodFill(int[][] image, int row, int col, int color) {
        int old = image[row][col];
        if (old == color) {
            return;
        }
        int rows = image.length;
        int cols = image[0].length;
        int[][] steps = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[] {row, col});
        while (!stack.isEmpty()) {
            int[] cell = stack.pop();
            int r = cell[0];
            int c = cell[1];
            // A cell can be on the stack twice. Skip it once it's painted.
            if (image[r][c] != old) {
                continue;
            }
            image[r][c] = color;
            for (int[] step : steps) {
                int nr = r + step[0];
                int nc = c + step[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && image[nr][nc] == old) {
                    stack.push(new int[] {nr, nc});
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int rows = in.nextInt();
        int cols = in.nextInt();
        int[][] image = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                image[r][c] = in.nextInt();
            }
        }
        int startRow = in.nextInt();
        int startCol = in.nextInt();
        int color = in.nextInt();
