	old := image[row][col]
	if old == color {
		return
	}
	rows, cols := len(image), len(image[0])
	steps := [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	stack := [][2]int{{row, col}}
	for len(stack) > 0 {
		cell := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		r, c := cell[0], cell[1]
		// A cell can be on the stack twice. Skip it once it's painted.
		if image[r][c] != old {
			continue
