import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function floodFill(image: number[][], row: number, col: number, color: number): void {
  const old = image[row]?.[col];
  if (old === undefined || old === color) {
    return;
  }
  const stack: [number, number][] = [[row, col]];
  for (let cell = stack.pop(); cell !== undefined; cell = stack.pop()) {
    const [r, c] = cell;
    const line = image[r];
    // A cell can be on the stack twice. Skip it once it's painted.
    if (line === undefined || line[c] !== old) {
      continue;
    }
    line[c] = color;
    const neighbors: [number, number][] = [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]];
    for (const [nr, nc] of neighbors) {
      // Off the grid, the lookup gives undefined, which is never the old color.
      if (image[nr]?.[nc] === old) {
        stack.push([nr, nc]);
      }
    }
  }
}

